'use client';

import { motion, AnimatePresence } from 'framer-motion';
import { useDesignStore } from '@/lib/store';
import { Button } from '@/components/ui/Button';
import { Trash2, Copy, X, Settings2, RotateCw, RotateCcw } from 'lucide-react';
import type { RoomSettings, SceneObject } from '@/lib/types';

const colors = [
  '#ffffff', '#f3f4f6', '#e5e7eb', '#d1d5db',
  '#fecaca', '#fed7aa', '#fef08a', '#d9f99d',
  '#bbf7d0', '#a5f3fc', '#bfdbfe', '#e9d5ff',
  '#f5d0fe', '#fecdd3', '#C6A85C', '#111111',
  '#8b4513', '#4a5568', '#2d3748', '#1a202c',
  '#ff6b6b', '#feca57', '#48dbfb', '#ff9ff3',
];

export function PropertyPanel() {
  const { 
    currentDesign, 
    selectedObjectId, 
    updateObject, 
    deleteObject, 
    duplicateObject,
    selectObject,
    updateRoomSettings,
    updateTableSeating,
    rotateObject,
  } = useDesignStore();

  if (!currentDesign) return null;

  const selectedObject = currentDesign.objects.find(obj => obj.id === selectedObjectId);

  const handleColorChange = (color: string) => {
    if (selectedObject) {
      updateObject(selectedObject.id, { color });
    }
  };

  const handleStyleChange = (style: string) => {
    if (selectedObject) {
      updateObject(selectedObject.id, { style });
    }
  };

  const handleScaleChange = (scale: number) => {
    if (selectedObject) {
      updateObject(selectedObject.id, { scale: [scale, scale, scale] });
    }
  };

  const handleRotate = (delta: number) => {
    if (selectedObject) {
      rotateObject(selectedObject.id, delta);
    }
  };

  return (
    <div className="h-full flex flex-col">
      <div className="p-4 lg:p-5 border-b border-[#E5E5E8] flex items-center justify-between">
        <div className="flex items-center gap-2 text-[#111111] font-semibold">
          <Settings2 className="w-5 h-5 text-[#C6A85C]" />
          <span>Properties</span>
        </div>
        {selectedObject && (
          <button
            onClick={() => selectObject(null)}
            className="p-1.5 hover:bg-[#F7F7F5] rounded-lg transition-colors"
          >
            <X className="w-4 h-4 text-[#8C8C92]" />
          </button>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 lg:p-5">
        <AnimatePresence mode="wait">
          {selectedObject ? (
            <ObjectProperties
              key="object"
              object={selectedObject}
              onColorChange={handleColorChange}
              onStyleChange={handleStyleChange}
              onScaleChange={handleScaleChange}
              onRotate={handleRotate}
              onDelete={() => deleteObject(selectedObject.id)}
              onDuplicate={() => duplicateObject(selectedObject.id)}
              onUpdateSeating={(capacity) => updateTableSeating(selectedObject.id, capacity)}
            />
          ) : (
            <RoomProperties
              key="room"
              settings={currentDesign.roomSettings}
              onUpdate={updateRoomSettings}
            />
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

function ObjectProperties({
  object,
  onColorChange,
  onStyleChange,
  onScaleChange,
  onRotate,
  onDelete,
  onDuplicate,
  onUpdateSeating,
}: {
  object: SceneObject;
  onColorChange: (color: string) => void;
  onStyleChange: (style: string) => void;
  onScaleChange: (scale: number) => void;
  onRotate: (delta: number) => void;
  onDelete: () => void;
  onDuplicate: () => void;
  onUpdateSeating?: (capacity: number) => void;
}) {
  const getStyleOptions = () => {
    switch (object.type) {
      case 'balloon-column':
      case 'balloon-arch':
        return ['classic', 'ombre', 'spiral'];
      case 'centerpiece':
        return ['floral', 'modern', 'minimal'];
      default:
        return [];
    }
  };

  const styleOptions = getStyleOptions();
  const isRoundTable = object.type === 'round-table';
  const isRectTable = object.type === 'rect-table';
  const isTable = isRoundTable || isRectTable;
  const isAutoGeneratedChair = object.isAutoGenerated;

  // Current rotation in degrees
  const rotationDeg = Math.round((object.rotation[1] * 180) / Math.PI);

  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 20 }}
      className="space-y-5"
    >
      <div>
        <span className="text-xs text-[#C6A85C] font-semibold uppercase tracking-wider">Selected</span>
        <h3 className="text-lg font-semibold text-[#111111] mt-1 capitalize">
          {object.type.replace('-', ' ')}
        </h3>
        <p className="text-xs text-[#8C8C92]">ID: {object.id.slice(0, 8)}</p>
        {isAutoGeneratedChair && (
          <p className="text-xs text-[#C6A85C] mt-1">Auto-generated • Drag to adjust</p>
        )}
      </div>

      {/* Table Seating Configuration */}
      {isTable && onUpdateSeating && (
        <div>
          <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">
            Seating Capacity
          </label>
          <div className="grid grid-cols-4 gap-2">
            {(isRoundTable ? [6, 8, 10, 12] : [4, 6, 8, 10]).map((capacity) => (
              <button
                key={capacity}
                onClick={() => onUpdateSeating(capacity)}
                className={`
                  px-2 py-2.5 rounded-xl text-sm font-medium transition-colors
                  ${object.seatingCapacity === capacity
                    ? 'bg-[#C6A85C] text-[#111111]'
                    : 'bg-[#F7F7F5] text-[#5A5A5F] hover:bg-[#E5E5E8]'
                  }
                `}
              >
                {capacity}
              </button>
            ))}
          </div>
          <p className="text-xs text-[#8C8C92] mt-2">
            Chairs auto-generate and follow table
          </p>
        </div>
      )}

      {/* Rotation Control */}
      <div>
        <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">
          Rotation: <span className="text-[#C6A85C]">{rotationDeg}°</span>
        </label>
        <div className="flex items-center gap-2">
          <button
            onClick={() => onRotate(-Math.PI / 4)}
            className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2.5 bg-[#F7F7F5] hover:bg-[#EFEFF2] rounded-xl text-[#5A5A5F] transition-colors"
          >
            <RotateCcw className="w-4 h-4" />
            <span className="text-sm">-45°</span>
          </button>
          <button
            onClick={() => onRotate(-Math.PI / 8)}
            className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2.5 bg-[#F7F7F5] hover:bg-[#EFEFF2] rounded-xl text-[#5A5A5F] transition-colors"
          >
            <span className="text-sm">-22°</span>
          </button>
          <button
            onClick={() => onRotate(Math.PI / 8)}
            className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2.5 bg-[#F7F7F5] hover:bg-[#EFEFF2] rounded-xl text-[#5A5A5F] transition-colors"
          >
            <span className="text-sm">+22°</span>
          </button>
          <button
            onClick={() => onRotate(Math.PI / 4)}
            className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2.5 bg-[#F7F7F5] hover:bg-[#EFEFF2] rounded-xl text-[#5A5A5F] transition-colors"
          >
            <RotateCw className="w-4 h-4" />
            <span className="text-sm">+45°</span>
          </button>
        </div>
      </div>

      {/* Color */}
      <div>
        <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">Color</label>
        <div className="grid grid-cols-6 gap-2">
          {colors.map((color) => (
            <motion.button
              key={color}
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => onColorChange(color)}
              className={`
                w-8 h-8 rounded-lg border-2 transition-all
                ${object.color === color 
                  ? 'border-[#C6A85C] ring-2 ring-[#C6A85C]/20' 
                  : 'border-[#E5E5E8] hover:border-[#C6A85C]'
                }
              `}
              style={{ backgroundColor: color }}
            />
          ))}
        </div>
      </div>

      {/* Style */}
      {styleOptions.length > 0 && (
        <div>
          <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">Style</label>
          <div className="flex flex-wrap gap-2">
            {styleOptions.map((style) => (
              <button
                key={style}
                onClick={() => onStyleChange(style)}
                className={`
                  px-4 py-2 rounded-xl text-sm capitalize transition-colors
                  ${object.style === style
                    ? 'bg-[#C6A85C] text-[#111111]'
                    : 'bg-[#F7F7F5] text-[#5A5A5F] hover:bg-[#E5E5E8]'
                  }
                `}
              >
                {style}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Scale */}
      <div>
        <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">
          Size: <span className="text-[#C6A85C]">{object.scale[0].toFixed(1)}x</span>
        </label>
        <input
          type="range"
          min="0.5"
          max="2"
          step="0.1"
          value={object.scale[0]}
          onChange={(e) => onScaleChange(parseFloat(e.target.value))}
          className="w-full h-2 bg-[#E5E5E8] rounded-lg appearance-none cursor-pointer accent-[#C6A85C]"
        />
      </div>

      {/* Actions */}
      <div className="pt-4 border-t border-[#E5E5E8] space-y-2">
        <Button onClick={onDuplicate} variant="outline" className="w-full border-[#E5E5E8]">
          <Copy className="w-4 h-4 mr-2" />
          Duplicate
        </Button>
        <Button onClick={onDelete} variant="outline" className="w-full text-red-500 border-red-200 hover:bg-red-50">
          <Trash2 className="w-4 h-4 mr-2" />
          {isAutoGeneratedChair ? 'Remove Chair' : 'Delete'}
        </Button>
      </div>
    </motion.div>
  );
}

function RoomProperties({
  settings,
  onUpdate,
}: {
  settings: RoomSettings;
  onUpdate: (settings: Partial<RoomSettings>) => void;
}) {
  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 20 }}
      className="space-y-6"
    >
      <div>
        <span className="text-xs text-[#C6A85C] font-semibold uppercase tracking-wider">Room</span>
        <h3 className="text-lg font-semibold text-[#111111] mt-1">Venue Settings</h3>
        <p className="text-xs text-[#8C8C92]">Customize your space</p>
      </div>

      {/* Wall Color */}
      <div>
        <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">Wall Color</label>
        <div className="grid grid-cols-6 gap-2">
          {colors.slice(0, 12).map((color) => (
            <motion.button
              key={color}
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => onUpdate({ wallColor: color })}
              className={`
                w-8 h-8 rounded-lg border-2 transition-all
                ${settings.wallColor === color 
                  ? 'border-[#C6A85C] ring-2 ring-[#C6A85C]/20' 
                  : 'border-[#E5E5E8] hover:border-[#C6A85C]'
                }
              `}
              style={{ backgroundColor: color }}
            />
          ))}
        </div>
      </div>

      {/* Floor Material */}
      <div>
        <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">Floor Material</label>
        <div className="grid grid-cols-2 gap-2">
          {(['wood', 'carpet', 'tile', 'grass'] as const).map((material) => (
            <button
              key={material}
              onClick={() => onUpdate({ floorMaterial: material })}
              className={`
                px-4 py-3 rounded-xl text-sm capitalize transition-colors
                ${settings.floorMaterial === material
                  ? 'bg-[#C6A85C] text-[#111111]'
                  : 'bg-[#F7F7F5] text-[#5A5A5F] hover:bg-[#E5E5E8]'
                }
              `}
            >
              {material}
            </button>
          ))}
        </div>
      </div>

      {/* Lighting */}
      <div>
        <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">Lighting</label>
        <div className="grid grid-cols-2 gap-2">
          {(['warm', 'cool', 'neutral', 'dramatic'] as const).map((preset) => (
            <button
              key={preset}
              onClick={() => onUpdate({ lightingPreset: preset })}
              className={`
                px-4 py-3 rounded-xl text-sm capitalize transition-colors
                ${settings.lightingPreset === preset
                  ? 'bg-[#C6A85C] text-[#111111]'
                  : 'bg-[#F7F7F5] text-[#5A5A5F] hover:bg-[#E5E5E8]'
                }
              `}
            >
              {preset}
            </button>
          ))}
        </div>
      </div>

      {/* Backdrop */}
      <div>
        <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">Backdrop</label>
        <div className="grid grid-cols-2 gap-2">
          {(['none', 'curtain', 'arch', 'wall'] as const).map((style) => (
            <button
              key={style}
              onClick={() => onUpdate({ backdropStyle: style })}
              className={`
                px-4 py-3 rounded-xl text-sm capitalize transition-colors
                ${settings.backdropStyle === style
                  ? 'bg-[#C6A85C] text-[#111111]'
                  : 'bg-[#F7F7F5] text-[#5A5A5F] hover:bg-[#E5E5E8]'
                }
              `}
            >
              {style}
            </button>
          ))}
        </div>
      </div>

      {/* Backdrop Color */}
      {settings.backdropStyle !== 'none' && (
        <div>
          <label className="text-sm font-medium text-[#5A5A5F] mb-3 block">Backdrop Color</label>
          <div className="grid grid-cols-6 gap-2">
            {colors.slice(0, 12).map((color) => (
              <motion.button
                key={color}
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => onUpdate({ backdropColor: color })}
                className={`
                  w-8 h-8 rounded-lg border-2 transition-all
                  ${settings.backdropColor === color 
                    ? 'border-[#C6A85C] ring-2 ring-[#C6A85C]/20' 
                    : 'border-[#E5E5E8] hover:border-[#C6A85C]'
                  }
                `}
                style={{ backgroundColor: color }}
              />
            ))}
          </div>
        </div>
      )}
    </motion.div>
  );
}
