'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Navbar } from '@/components/layout/Navbar';
import { Button } from '@/components/ui/Button';
import { useDesignStore } from '@/lib/store';
import { CategoryPanel } from '@/components/studio/CategoryPanel';
import { PropertyPanel } from '@/components/studio/PropertyPanel';
import { Save, Eye, ArrowLeft, RotateCcw, Menu, X } from 'lucide-react';
import Link from 'next/link';
import dynamic from 'next/dynamic';

// Dynamic import Scene3D
const Scene3D = dynamic(() => import('@/components/3d/Scene3D').then(mod => mod.Scene3D), {
  ssr: false,
  loading: () => (
    <div className="w-full h-full bg-gradient-to-b from-gray-900 to-gray-800 flex items-center justify-center">
      <div className="text-white/60 text-sm">Loading 3D Studio...</div>
    </div>
  ),
});

export default function StudioPage() {
  const router = useRouter();
  const { currentDesign, saveDesign, resetScene } = useDesignStore();
  const [isClient, setIsClient] = useState(false);
  const [showLeftPanel, setShowLeftPanel] = useState(true);
  const [showRightPanel, setShowRightPanel] = useState(true);
  const [showMobilePanel, setShowMobilePanel] = useState<'none' | 'add' | 'properties'>('none');

  useEffect(() => {
    setIsClient(true);
    if (!currentDesign) {
      router.push('/templates');
    }
  }, [currentDesign, router]);

  // Close panels on mobile when design changes
  useEffect(() => {
    setShowMobilePanel('none');
  }, [currentDesign?.id]);

  if (!isClient) {
    return (
      <div className="h-screen flex flex-col bg-[#F7F7F5]">
        <Navbar />
        <div className="flex-1 flex items-center justify-center">
          <div className="text-[#5A5A5F]">Loading Studio...</div>
        </div>
      </div>
    );
  }

  if (!currentDesign) return null;

  const handleSave = () => saveDesign();
  
  const handleReset = () => {
    if (confirm('Reset your design?')) resetScene();
  };

  return (
    <div className="h-screen flex flex-col bg-[#F7F7F5]">
      <Navbar />
      
      {/* Header */}
      <div className="pt-16 lg:pt-20 bg-white border-b border-[#E5E5E8] shrink-0">
        <div className="px-4 sm:px-6 lg:px-8 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Link href="/templates">
              <Button variant="ghost" size="sm">
                <ArrowLeft className="w-4 h-4 mr-2" />
                Exit
              </Button>
            </Link>
            <div>
              <h1 className="text-lg font-semibold">{currentDesign.name}</h1>
              <p className="text-xs text-[#8C8C92]">{currentDesign.objects.length} objects</p>
            </div>
          </div>
          
          {/* Desktop controls */}
          <div className="hidden md:flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={handleReset}>
              <RotateCcw className="w-4 h-4 mr-2" />
              Reset
            </Button>
            <Button variant="outline" size="sm" onClick={handleSave}>
              <Save className="w-4 h-4 mr-2" />
              Save
            </Button>
            <Link href="/preview">
              <Button size="sm" className="bg-[#C6A85C]">
                <Eye className="w-4 h-4 mr-2" />
                Preview
              </Button>
            </Link>
          </div>

          {/* Mobile menu button */}
          <div className="flex md:hidden items-center gap-2">
            <button
              onClick={() => setShowMobilePanel(showMobilePanel === 'add' ? 'none' : 'add')}
              className={`p-2 rounded-lg ${showMobilePanel === 'add' ? 'bg-[#C6A85C]/20 text-[#C6A85C]' : 'text-[#5A5A5F]'}`}
            >
              <Menu className="w-5 h-5" />
            </button>
            <button
              onClick={() => setShowMobilePanel(showMobilePanel === 'properties' ? 'none' : 'properties')}
              className={`p-2 rounded-lg ${showMobilePanel === 'properties' ? 'bg-[#C6A85C]/20 text-[#C6A85C]' : 'text-[#5A5A5F]'}`}
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
              </svg>
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex overflow-hidden">
        {/* Left Panel - CategoryPanel */}
        <div className={`
          ${showLeftPanel ? 'w-72' : 'w-0'} 
          hidden lg:block bg-white border-r border-[#E5E5E8] transition-all duration-300 overflow-hidden
        `}>
          <CategoryPanel />
        </div>

        {/* Center - 3D Scene */}
        <div className="flex-1 relative bg-[#F0EFE9]">
          <Scene3D />
          
          {/* Mobile panel overlay */}
          {showMobilePanel !== 'none' && (
            <div className="absolute inset-0 z-50 bg-black/20" onClick={() => setShowMobilePanel('none')}>
              <div 
                className="absolute bottom-0 left-0 right-0 bg-white rounded-t-2xl shadow-2xl max-h-[70vh] overflow-hidden"
                onClick={e => e.stopPropagation()}
              >
                <div className="flex items-center justify-between p-4 border-b border-[#E5E5E8]">
                  <span className="font-semibold">
                    {showMobilePanel === 'add' ? 'Add Elements' : 'Properties'}
                  </span>
                  <button onClick={() => setShowMobilePanel('none')}>
                    <X className="w-5 h-5 text-[#8C8C92]" />
                  </button>
                </div>
                <div className="h-[50vh] overflow-y-auto">
                  {showMobilePanel === 'add' ? (
                    <CategoryPanel onClose={() => setShowMobilePanel('none')} />
                  ) : (
                    <PropertyPanel />
                  )}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Right Panel - PropertyPanel */}
        <div className={`
          ${showRightPanel ? 'w-80' : 'w-0'} 
          hidden lg:block bg-white border-l border-[#E5E5E8] transition-all duration-300 overflow-hidden
        `}>
          <PropertyPanel />
        </div>
      </div>
    </div>
  );
}
